_DEFAULT_STATIONS = [
    {"name": "Groove Salad (ambient)", "url": "https://ice1.somafm.com/groovesalad-128-mp3"},
    {"name": "Folk Forward", "url": "https://ice1.somafm.com/folkfwd-128-mp3"},
    {"name": "Indie Pop Rocks", "url": "https://ice1.somafm.com/indiepop-128-mp3"},
    {"name": "Beat Blender", "url": "https://ice1.somafm.com/beatblender-128-mp3"},
    {"name": "Secret Agent", "url": "https://ice1.somafm.com/secretagent-128-mp3"},
]


def stations():
    raw = os.getenv("MUSIC_STATIONS")
    if raw:
        try:
            lst = json.loads(raw)
            out = [{"name": str(x["name"])[:60], "url": str(x["url"])} for x in lst
                   if isinstance(x, dict) and str(x.get("url", "")).startswith("https://")]
            if out:
                return out[:20]
        except Exception:
            pass
    return _DEFAULT_STATIONS


def media_hosts():
    hosts = []
    for st in stations():
        h = urlparse(st["url"]).netloc
        if h and h not in hosts:
            hosts.append(h)
    return " ".join("https://" + h for h in hosts)


MAX_BODY = 8 * 1024 * 1024
MAX_PHOTO = 6 * 1024 * 1024
NS = None

_hits = {}
_hits_lock = threading.Lock()


def N(name):
    return NS[name]


def rate_ok(key, limit, window=60):
    now = time.time()
    with _hits_lock:
        if len(_hits) > 20000:
            for k in [k for k, v in _hits.items() if not v or now - v[-1] > window]:
                _hits.pop(k, None)
        q = [x for x in _hits.get(key, []) if now - x < window]
        if len(q) >= limit:
            _hits[key] = q
            return False
        q.append(now)
        _hits[key] = q
        return True


class ApiError(Exception):
    def __init__(self, status, code):
        Exception.__init__(self, code)
        self.status = status
        self.code = code


def row_get(row, key, default=None):
    try:
        v = row[key]
    except Exception:
        return default
    return default if v is None else v


def clean(v, n):
    if not isinstance(v, str):
        raise ApiError(400, "invalid")
    v = re.sub(r"[\x00-\x1f\x7f]", " ", v).strip()
    if not v or len(v) > n:
        raise ApiError(400, "invalid")
    return v


def num(v, lo, hi):
    try:
        x = float(v)
    except Exception:
        raise ApiError(400, "invalid")
    if not (lo <= x <= hi) or x != x:
        raise ApiError(400, "invalid")
    return x


def photo_bytes(data_url):
    if not isinstance(data_url, str) or len(data_url) > MAX_PHOTO * 2:
        raise ApiError(400, "photo")
    m = re.match(r"^data:image/(jpeg|png|webp);base64,([A-Za-z0-9+/=\s]+)$", data_url)
    if not m:
        raise ApiError(400, "photo")
    try:
        raw = base64.b64decode(m.group(2), validate=False)
    except Exception:
        raise ApiError(400, "photo")
    if not raw or len(raw) > MAX_PHOTO:
        raise ApiError(400, "photo")
    ok = raw[:3] == b"\xff\xd8\xff" or raw[:8] == b"\x89PNG\r\n\x1a\n" or (raw[:4] == b"RIFF" and raw[8:12] == b"WEBP")
    if not ok:
        raise ApiError(400, "photo")
    return raw


