def user_dict(uid):
    u = N("get_user")(uid)
    admin = uid == N("ADMIN_ID")
    registered = bool(N("is_complete")(u))
    d = {"id": uid, "admin": admin, "registered": registered, "lang": row_get(u, "lang", "uz") if u else "uz",
         "terms_ok": bool(row_get(u, "terms_at")) if u else False,
         "unread": (N("q_one")("SELECT COUNT(*) AS c FROM notifications WHERE user_id=? AND is_read=0", (uid,)) or {"c": 0})["c"]}
    if registered:
        cnt = row_get(u, "rating_count", 0) or 0
        d.update({
            "role": u["role"], "name": u["full_name"], "phone": u["phone"],
            "verified": bool(row_get(u, "verified", 0)),
            "car_brand": row_get(u, "car_brand", ""), "car_model": row_get(u, "car_model", ""),
            "car_plate": row_get(u, "car_plate", ""),
            "rating_count": cnt,
            "rating_avg": round((row_get(u, "rating_sum", 0) or 0) / cnt, 1) if cnt else 0,
        })
    return d


def km_between(a_lat, a_lon, b_lat, b_lon):
    if None in (a_lat, a_lon, b_lat, b_lon):
        return None
    try:
        return round(N("haversine")(a_lat, a_lon, b_lat, b_lon), 1)
    except Exception:
        return None


def cargo_dict(c, viewer_id, role, lat=None, lon=None, detail=False):
    d = {
        "id": c["id"], "type": c["cargo_type"], "weight": c["weight"], "from": c["from_loc"], "to": c["to_loc"],
        "price": round(c["price"] or 0), "status": c["status"],
        "distance_km": row_get(c, "road_km") or km_between(row_get(c, "lat"), row_get(c, "lon"), row_get(c, "to_lat"), row_get(c, "to_lon")),
        "road": bool(row_get(c, "road_km")), "lat": row_get(c, "lat"), "lon": row_get(c, "lon"),
        "to_lat": row_get(c, "to_lat"), "to_lon": row_get(c, "to_lon"),
        "away_km": None, "counterpart": None, "my_fee": None, "can_deliver": False,
        "created_at": row_get(c, "created_at"), "taken_at": row_get(c, "taken_at"), "delivered_at": row_get(c, "delivered_at"),
        "agreed_driver": bool(row_get(c, "driver_agreed_at")), "agreed_owner": bool(row_get(c, "owner_agreed_at")),
        "can_agree": False, "can_rate": False, "has_doc": c["status"] in ("taken", "delivered"),
    }
    if lat is not None and lon is not None:
        d["away_km"] = km_between(lat, lon, row_get(c, "lat"), row_get(c, "lon"))
    if role == "driver":
        d["fee_est"] = round((c["price"] or 0) * N("DRIVER_FOIZ"))
    if detail:
        if role == "owner" and c["driver_id"]:
            dr = N("get_user")(c["driver_id"])
            if dr:
                cnt = row_get(dr, "rating_count", 0) or 0
                d["counterpart"] = {
                    "name": dr["full_name"], "phone": dr["phone"],
                    "car": ((row_get(dr, "car_brand", "") or "") + " " + (row_get(dr, "car_model", "") or "")).strip(),
                    "plate": row_get(dr, "car_plate", ""),
                    "rating": round((row_get(dr, "rating_sum", 0) or 0) / cnt, 1) if cnt else 0,
                }
            who = "owner"
        elif role == "driver":
            ow = N("get_user")(c["owner_id"])
            if ow:
                d["counterpart"] = {"name": ow["full_name"], "phone": ow["phone"]}
            who = "driver"
            d["can_deliver"] = c["status"] == "taken"
        else:
            who = None
        if role == "owner":
            d["can_agree"] = c["status"] in ("taken", "delivered") and not row_get(c, "owner_agreed_at")
        if c["status"] == "delivered":
            d["can_rate"] = not row_get(c, "rated" if role == "owner" else "driver_rated", 0)
        if who and (row_get(c, who + "_fee", 0) or 0) > 0:
            d["my_fee"] = {"amount": round(c[who + "_fee"]), "paid": bool(row_get(c, who + "_paid", 0)),
                           "pay_req": bool(row_get(c, who + "_pay_req", 0))}
    return d


def unpaid_fees(uid, role):
    rows = N("q_all")(
        "SELECT * FROM cargos WHERE " + role + "_id=? AND " + role + "_fee>0 AND " + role + "_paid=0 ORDER BY id",
        (uid,))
    return [{"cargo_id": r["id"], "fee": round(r[role + "_fee"]), "pay_req": bool(row_get(r, role + "_pay_req", 0)),
             "who": role} for r in rows]


# ------------------------------------------------------------------ marshrutlar

def require_user(h):
    s = h.session()
    uid = N("session_user_id")(s) if s else None
    if not uid:
        raise ApiError(401, "unauthorized")
    if uid in N("blocked_ids"):
        raise ApiError(403, "blocked")
    if not rate_ok("u:" + str(uid), 240):
        raise ApiError(429, "rate")
    return uid


def need_registered(uid, role=None):
    u = N("get_user")(uid)
    if not N("is_complete")(u):
        raise ApiError(403, "invalid")
    if role and u["role"] != role:
        raise ApiError(403, "bad_action")
    return u


def route(h, method, path, q, body):
    if path == "/api/config" and method == "GET":
        return {"bot": N("BOT_USERNAME"), "owner_pct": N("OWNER_FOIZ") * 100, "driver_pct": N("DRIVER_FOIZ") * 100}

    if path == "/api/login/start" and method == "POST":
        if not rate_ok("login:" + h.ip(), 12):
            raise ApiError(429, "rate")
        tok = N("create_login_token")()
        return {"token": tok, "link": "https://t.me/" + N("BOT_USERNAME") + "?start=login_" + tok}

    if path == "/api/login/check" and method == "GET":
        if not rate_ok("check:" + h.ip(), 90):
            raise ApiError(429, "rate")
        tok = (q.get("token") or [""])[0]
        if not re.match(r"^[A-Za-z0-9_\-]{10,64}$", tok):
            return {"status": "expired"}
        st, sess, uid = N("poll_login_token")(tok)
        if st == "ok" and uid in N("blocked_ids"):
            N("delete_session")(sess)
            raise ApiError(403, "blocked")
        return {"status": st, "session": sess} if st == "ok" else {"status": st}

    uid = require_user(h)

    if path.startswith("/api/admin/"):
        if uid != N("ADMIN_ID"):
            raise ApiError(403, "forbidden")
        return admin_route(method, path, q, body)

    if path == "/api/logout" and method == "POST":
        N("delete_session")(h.session())
        return {"ok": True}

    if path == "/api/me" and method == "GET":
        return user_dict(uid)

    if path == "/api/lang" and method == "POST":
        l = body.get("lang")
        if l not in ("uz", "ru"):
            raise ApiError(400, "invalid")
        N("lang_cache")[uid] = l
        if N("get_user")(uid):
            N("save_user")(uid, lang=l)
        else:
            N("save_user")(uid, lang=l)
        return {"ok": True}

    if path == "/api/register" and method == "POST":
        return register(uid, body)

    if path == "/api/cargos/open" and method == "GET":
        u = need_registered(uid, "driver")
        if not row_get(u, "verified", 0):
            raise ApiError(403, "not_verified")
        lat = lon = None
        if "lat" in q and "lon" in q:
            lat = num(q["lat"][0], -90, 90)
            lon = num(q["lon"][0], -180, 180)
        items = [cargo_dict(c, uid, "driver", lat, lon) for c in N("open_cargos")()[:200]]
        if lat is not None:
            items.sort(key=lambda x: (x["away_km"] is None, x["away_km"] if x["away_km"] is not None else 0))
        return {"cargos": items[:60]}

    if path == "/api/cargos/mine" and method == "GET":
        u = need_registered(uid)
        if u["role"] == "owner":
            rows = N("owner_cargos")(uid)
        else:
            rows = N("driver_cargos")(uid)
        return {"cargos": [cargo_dict(c, uid, u["role"], detail=True) for c in rows[:100]]}

    if path == "/api/cargos" and method == "POST":
        need_registered(uid, "owner")
        if not rate_ok("post:" + str(uid), 10, 3600):
            raise ApiError(429, "rate")
        if N("unpaid_owner_cargo")(uid):
            raise ApiError(409, "pay_first")
        price = N("parse_som")(clean(body.get("price"), 30))
        if price is None or not (1 <= price <= 10_000_000_000):
            raise ApiError(400, "invalid")
        lat = lon = None
        if body.get("lat") is not None and body.get("lon") is not None:
            lat = num(body["lat"], -90, 90)
            lon = num(body["lon"], -180, 180)
        tlat = tlon = None
        if body.get("to_lat") is not None and body.get("to_lon") is not None:
            tlat = num(body["to_lat"], -90, 90)
            tlon = num(body["to_lon"], -180, 180)
        road = None
        if lat is not None and tlat is not None:
            rr = road_route(lat, lon, tlat, tlon)
            road = rr["km"] if rr else km_between(lat, lon, tlat, tlon)
        ct, wt = clean(body.get("cargo_type"), 80), clean(body.get("weight"), 40)
        fl, tl = clean(body.get("from_loc"), 100), clean(body.get("to_loc"), 100)
        cid = N("add_cargo")(owner_id=uid, cargo_type=ct, weight=wt, from_loc=fl, to_loc=tl, price=price,
                             lat=lat, lon=lon, to_lat=tlat, to_lon=tlon, road_km=road, status="open")
        esc = N("esc")
        N("notify_admin")("Yangi yuk #" + str(cid) + " (ilova): " + esc(ct) + ", " + esc(fl) + " -> " + esc(tl)
                          + ", " + N("money")(price) + " so'm")
        return {"id": cid}

    m = re.match(r"^/api/cargos/(\d{1,12})/(take|deliver)$", path)
    if m and method == "POST":
        cid = int(m.group(1))
        need_registered(uid, "driver")
        if not rate_ok("act:" + str(uid), 30):
            raise ApiError(429, "rate")
        if m.group(2) == "take":
            err, _ = N("take_cargo_core")(uid, cid)
            if err:
                code = {"take_gone": "gone", "take_only_ver": "not_verified", "take_pay_first": "pay_first"}.get(err, "bad_action")
                raise ApiError(409 if code in ("gone", "pay_first") else 403, code)
        else:
            err = N("deliver_cargo_core")(uid, cid)
            if err:
                raise ApiError(409, "bad_action")
        return {"ok": True}

    if path == "/api/fees" and method == "GET":
        u = need_registered(uid)
        return {"fees": unpaid_fees(uid, u["role"]), "card": N("ADMIN_CARD"), "card_digits": N("CARD_DIGITS")}

    m = re.match(r"^/api/fees/(\d{1,12})/receipt$", path)
    if m and method == "POST":
        u = need_registered(uid)
        if not rate_ok("rcpt:" + str(uid), 10, 600):
            raise ApiError(429, "rate")
        raw = photo_bytes(body.get("photo"))
        err = N("submit_receipt_core")(uid, int(m.group(1)), u["role"], photo_bytes=raw)
        if err:
            raise ApiError(409, "bad_action")
        return {"ok": True}

    if path.startswith("/api/geo/") and method == "GET":
        if not rate_ok("geo:" + str(uid), 40):
            raise ApiError(429, "rate")
        try:
            if path == "/api/geo/search":
                text = clean((q.get("q") or [""])[0], 80)
                return {"results": geo_search(text)}
            if path == "/api/geo/reverse":
                return geo_reverse(num((q.get("lat") or [""])[0], -90, 90), num((q.get("lon") or [""])[0], -180, 180))
            if path == "/api/geo/route":
                g = [num((q.get(k) or [""])[0], -180, 180) for k in ("from_lat", "from_lon", "to_lat", "to_lon")]
                r = road_route(g[0], g[1], g[2], g[3])
                if not r:
                    r = {"km": km_between(g[0], g[1], g[2], g[3]), "minutes": None, "approx": True}
                return r
        except ApiError:
            raise
        except Exception as e:
            print("Geo xatosi:", e)
            raise ApiError(502, "network")
        raise ApiError(404, "not_found")

    if path == "/api/music" and method == "GET":
        return {"stations": stations()}

    if path == "/api/support" and method == "GET":
        rows = N("q_all")("SELECT id, from_admin, text, created_at FROM support_msgs WHERE user_id=? ORDER BY id DESC LIMIT 100", (uid,))
        return {"messages": [{"id": r["id"], "admin": bool(r["from_admin"]), "text": r["text"], "at": r["created_at"]} for r in reversed(rows)]}

    if path == "/api/support" and method == "POST":
        text = clean(body.get("text"), 1000)
        if not rate_ok("sup:" + str(uid), 10, 600):
            raise ApiError(429, "rate")
        u = N("get_user")(uid)
        N("record_support")(uid, False, text)
        name = u["full_name"] if u and u["full_name"] else "?"
        phone = u["phone"] if u and u["phone"] else "-"
        types, bot, esc = N("types"), N("bot"), N("esc")
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("Javob yozish", callback_data="replyto_" + str(uid)))
        try:
            sent = bot.send_message(N("ADMIN_ID"), "Yordam so'rovi (ilova)\n" + esc(name) + "\n" + esc(phone) + "\nID: " + str(uid) + "\n\n" + esc(text), reply_markup=kb)
            N("save_help_map")(sent.message_id, uid)
        except Exception as e:
            print("Yordam xabarini adminga yuborishda xato:", e)
        return {"ok": True}

    if path == "/api/account/delete" and method == "POST":
        if body.get("confirm") is not True:
            raise ApiError(400, "invalid")
        err = N("delete_account_core")(uid)
        if err == "delete_active":
            raise ApiError(409, "delete_active")
        if err == "delete_unpaid":
            raise ApiError(409, "delete_unpaid")
        if err:
            raise ApiError(400, "invalid")
        return {"ok": True}

    if path == "/api/notes" and method == "GET":
        rows = N("q_all")("SELECT id, text, cargo_id, is_read, created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 60", (uid,))
        return {"notes": [{"id": r["id"], "text": r["text"], "cargo_id": r["cargo_id"], "read": bool(r["is_read"]),
                           "at": r["created_at"]} for r in rows]}

    if path == "/api/notes/read" and method == "POST":
        N("q_exec")("UPDATE notifications SET is_read=1 WHERE user_id=?", (uid,))
        return {"ok": True}

    if path == "/api/terms" and method == "POST":
        import datetime
        if body.get("accept") is not True:
            raise ApiError(400, "consent")
        N("save_user")(uid, terms_at=str(datetime.datetime.now()))
        return {"ok": True}

    m = re.match(r"^/api/cargos/(\d{1,12})/(agree|rate|document)$", path)
    if m:
        cid, act = int(m.group(1)), m.group(2)
        u = need_registered(uid)
        c = N("get_cargo")(cid)
        if not c or uid not in (c["owner_id"], row_get(c, "driver_id")):
            raise ApiError(404, "gone")
        if act == "document" and method == "GET":
            return document(c, u)
        if act == "agree" and method == "POST":
            if N("agree_core")(uid, cid):
                raise ApiError(409, "bad_action")
            return {"ok": True}
        if act == "rate" and method == "POST":
            st = body.get("stars")
            if not isinstance(st, int) or isinstance(st, bool):
                raise ApiError(400, "invalid")
            cm = body.get("comment") or ""
            if not isinstance(cm, str):
                raise ApiError(400, "invalid")
            err = N("rate_core")(uid, cid, st, re.sub(r"[\x00-\x1f]", " ", cm).strip()[:300])
            if err == "rate_dup":
                raise ApiError(409, "bad_action")
            if err:
                raise ApiError(400, "invalid")
            return {"ok": True}

    if path == "/api/location" and method == "POST":
        need_registered(uid, "driver")
        N("save_driver_location")(uid, num(body.get("lat"), -90, 90), num(body.get("lon"), -180, 180))
        return {"ok": True}

    raise ApiError(404, "not_found")


def _cnt(sql, *a):
    return (N("q_one")(sql, a) or {"c": 0})["c"] or 0


def _fetch_photo(file_id):
    bot = N("bot")
    info = bot.get_file(file_id)
    return bot.download_file(info.file_path)


def admin_route(method, path, q, body):
    qo, qa, qe = N("q_one"), N("q_all"), N("q_exec")
    adm = N("ADMIN_ID")
    esc = N("esc")

    if path == "/api/admin/stats" and method == "GET":
        pend = _cnt("SELECT COUNT(*) AS c FROM cargos WHERE (owner_pay_req=1 AND owner_paid=0) OR (driver_pay_req=1 AND driver_paid=0)")
        unpaid = qo("SELECT (SELECT COALESCE(SUM(owner_fee),0) FROM cargos WHERE owner_paid=0 AND owner_fee>0) AS a, "
                    "(SELECT COALESCE(SUM(driver_fee),0) FROM cargos WHERE driver_paid=0 AND driver_fee>0) AS b")
        return {
            "drivers": _cnt("SELECT COUNT(*) AS c FROM users WHERE role='driver' AND user_id<>?", adm),
            "pending_drivers": _cnt("SELECT COUNT(*) AS c FROM users WHERE role='driver' AND verified=0 AND user_id<>?", adm),
            "owners": _cnt("SELECT COUNT(*) AS c FROM users WHERE role='owner' AND user_id<>?", adm),
            "blocked": _cnt("SELECT COUNT(*) AS c FROM users WHERE blocked=1"),
            "cargos": _cnt("SELECT COUNT(*) AS c FROM cargos"),
            "open": _cnt("SELECT COUNT(*) AS c FROM cargos WHERE status='open'"),
            "taken": _cnt("SELECT COUNT(*) AS c FROM cargos WHERE status='taken'"),
            "delivered": _cnt("SELECT COUNT(*) AS c FROM cargos WHERE status='delivered'"),
            "pending_payments": pend,
            "balance": round(N("get_admin_balance")()), "withdrawn": round(N("get_setting")("admin_withdrawn") or 0),
            "unpaid_total": round((unpaid["a"] or 0) + (unpaid["b"] or 0)),
        }

    if path == "/api/admin/pending" and method == "GET":
        rows = qa("SELECT * FROM users WHERE role='driver' AND verified=0 AND user_id<>? ORDER BY created_at LIMIT 50", (adm,))
        return {"drivers": [{"id": r["user_id"], "name": r["full_name"], "phone": r["phone"],
                             "car": ((r["car_brand"] or "") + " " + (r["car_model"] or "")).strip(), "plate": r["car_plate"],
                             "has_photo": bool(row_get(r, "verify_photo")), "created_at": row_get(r, "created_at")} for r in rows]}

    m = re.match(r"^/api/admin/photo/(\d{1,15})$", path)
    if m and method == "GET":
        r = N("get_user")(int(m.group(1)))
        if not r or not row_get(r, "verify_photo"):
            raise ApiError(404, "gone")
        try:
            return ("raw", _fetch_photo(r["verify_photo"]), "image/jpeg")
        except Exception as e:
            print("Admin: rasm olinmadi:", e)
            raise ApiError(502, "upload")

    m = re.match(r"^/api/admin/drivers/(\d{1,15})/(verify|reject)$", path)
    if m and method == "POST":
        tid, act = int(m.group(1)), m.group(2)
        r = N("get_user")(tid)
        if not r or r["role"] != "driver":
            raise ApiError(404, "gone")
        if act == "verify":
            N("save_user")(tid, verified=1, verify_photo=None)
            N("safe_send")(tid, N("T")(tid, "verified_msg"), reply_markup=N("main_menu")(tid, "driver"))
        else:
            N("save_user")(tid, role=None, verified=0, verify_photo=None)
            N("safe_send")(tid, N("T")(tid, "rejected_msg"))
        return {"ok": True}

    if path == "/api/admin/payments" and method == "GET":
        out = []
        for who in ("owner", "driver"):
            for r in qa("SELECT * FROM cargos WHERE " + who + "_pay_req=1 AND " + who + "_paid=0 AND " + who + "_fee>0 ORDER BY id"):
                u = N("get_user")(r[who + "_id"])
                out.append({"cargo_id": r["id"], "who": who, "name": u["full_name"] if u else "?", "phone": u["phone"] if u else "",
                            "amount": round(r[who + "_fee"]), "has_receipt": bool(row_get(r, who + "_receipt"))})
        return {"payments": out, "card": N("ADMIN_CARD")}

    m = re.match(r"^/api/admin/receipt/(\d{1,12})/(owner|driver)$", path)
    if m and method == "GET":
        r = N("get_cargo")(int(m.group(1)))
        fid = row_get(r, m.group(2) + "_receipt") if r else None
        if not fid:
            raise ApiError(404, "gone")
        try:
            return ("raw", _fetch_photo(fid), "image/jpeg")
        except Exception as e:
            print("Admin: chek rasmi olinmadi:", e)
            raise ApiError(502, "upload")

    m = re.match(r"^/api/admin/payments/(\d{1,12})/(owner|driver)/confirm$", path)
    if m and method == "POST":
        cid, who = int(m.group(1)), m.group(2)
        r = N("get_cargo")(cid)
        if not r or r[who + "_paid"] or not (r[who + "_fee"] or 0) > 0:
            raise ApiError(409, "bad_action")
        N("update_cargo")(cid, **{who + "_paid": 1})
        N("add_admin_balance")(r[who + "_fee"])
        uid2 = r[who + "_id"]
        N("safe_send")(uid2, N("T")(uid2, who + "_pay_confirmed"))
        return {"ok": True}

    if path == "/api/admin/users" and method == "GET":
        term = ((q.get("q") or [""])[0]).strip()[:40]
        role = (q.get("role") or [""])[0]
        sql, par = "SELECT * FROM users WHERE user_id<>?", [adm]
        if role in ("driver", "owner"):
            sql += " AND role=?"; par.append(role)
        if (q.get("blocked") or [""])[0] == "1":
            sql += " AND blocked=1"
        if term:
            like = "%" + term.replace("%", "").replace("_", "") + "%"
            sql += " AND (full_name LIKE ? OR phone LIKE ? OR CAST(user_id AS TEXT) LIKE ?)"
            par += [like, like, like]
        rows = qa(sql + " ORDER BY created_at DESC LIMIT 50", tuple(par))
        return {"users": [{"id": r["user_id"], "role": r["role"], "name": r["full_name"], "phone": r["phone"],
                           "verified": bool(row_get(r, "verified", 0)), "blocked": bool(row_get(r, "blocked", 0)),
                           "car": ((row_get(r, "car_brand", "") or "") + " " + (row_get(r, "car_model", "") or "")).strip(),
                           "plate": row_get(r, "car_plate", ""),
                           "rating": round((row_get(r, "rating_sum", 0) or 0) / r["rating_count"], 1) if row_get(r, "rating_count", 0) else 0,
                           "rating_count": row_get(r, "rating_count", 0)} for r in rows]}

    m = re.match(r"^/api/admin/users/(\d{1,15})/(block|message)$", path)
    if m and method == "POST":
        tid, act = int(m.group(1)), m.group(2)
        if tid == adm or not N("get_user")(tid):
            raise ApiError(404, "gone")
        if act == "block":
            on = body.get("blocked") is True
            qe("UPDATE users SET blocked=? WHERE user_id=?", (1 if on else 0, tid))
            if on:
                N("blocked_ids").add(tid)
                N("delete_all_sessions")(tid)
                N("safe_send")(tid, N("T")(tid, "blocked"))
            else:
                N("blocked_ids").discard(tid)
                N("safe_send")(tid, N("T")(tid, "unblocked"))
            return {"ok": True}
        text = clean(body.get("text"), 1000)
        N("record_support")(tid, True, text)
        N("safe_send")(tid, N("T")(tid, "admin_says", text=esc(text)))
        return {"ok": True}

    if path == "/api/admin/cargos" and method == "GET":
        st = (q.get("status") or [""])[0]
        sql, par = "SELECT * FROM cargos", ()
        if st in ("open", "taken", "delivered"):
            sql += " WHERE status=?"; par = (st,)
        rows = qa(sql + " ORDER BY id DESC LIMIT 60", par)
        out = []
        for r in rows:
            ow, dr = N("get_user")(r["owner_id"]), (N("get_user")(r["driver_id"]) if row_get(r, "driver_id") else None)
            out.append({"id": r["id"], "type": r["cargo_type"], "from": r["from_loc"], "to": r["to_loc"], "price": round(r["price"] or 0),
                        "status": r["status"], "owner": ow["full_name"] if ow else "?", "driver": dr["full_name"] if dr else None,
                        "owner_paid": bool(row_get(r, "owner_paid", 0)), "driver_paid": bool(row_get(r, "driver_paid", 0))})
        return {"cargos": out}

    if path == "/api/admin/locations" and method == "GET":
        rows = qa("SELECT u.user_id, u.full_name, u.phone, u.car_plate, d.lat, d.lon, d.updated_at FROM driver_locations d "
                  "JOIN users u ON u.user_id=d.user_id ORDER BY d.updated_at DESC LIMIT 100")
        return {"drivers": [{"id": r["user_id"], "name": r["full_name"], "phone": r["phone"], "plate": r["car_plate"],
                             "lat": r["lat"], "lon": r["lon"], "at": r["updated_at"]} for r in rows]}

    if path == "/api/admin/support" and method == "GET":
        rows = qa("SELECT s.user_id, s.from_admin, s.text, s.created_at FROM support_msgs s JOIN "
                  "(SELECT user_id, MAX(id) AS mid FROM support_msgs GROUP BY user_id) m ON s.id=m.mid ORDER BY s.id DESC LIMIT 40")
        out = []
        for r in rows:
            u = N("get_user")(r["user_id"])
            out.append({"id": r["user_id"], "name": u["full_name"] if u else "?", "phone": u["phone"] if u else "",
                        "last": r["text"], "at": r["created_at"], "needs_reply": not r["from_admin"]})
        return {"threads": out}

    m = re.match(r"^/api/admin/support/(\d{1,15})$", path)
    if m and method == "GET":
        rows = qa("SELECT id, from_admin, text, created_at FROM support_msgs WHERE user_id=? ORDER BY id DESC LIMIT 100", (int(m.group(1)),))
        return {"messages": [{"id": r["id"], "admin": bool(r["from_admin"]), "text": r["text"], "at": r["created_at"]} for r in reversed(rows)]}

    if path == "/api/admin/balance/reset" and method == "POST":
        cur = N("get_admin_balance")()
        if cur:
            N("set_setting")("admin_withdrawn", N("get_setting")("admin_withdrawn") + cur)
            N("set_setting")("admin_balance", 0)
        return {"ok": True}

    if path == "/api/admin/broadcast" and method == "POST":
        text = clean(body.get("text"), 1000)
        grp = body.get("group")
        where = {"all": "1=1", "driver": "role='driver'", "owner": "role='owner'"}.get(grp)
        if not where:
            raise ApiError(400, "invalid")
        rows = qa("SELECT user_id FROM users WHERE " + where + " AND user_id<>? AND COALESCE(blocked,0)=0", (adm,))
        ids = [r["user_id"] for r in rows]

        def run():
            for i in ids:
                N("safe_send")(i, text)
                time.sleep(0.06)
        threading.Thread(target=run, daemon=True).start()
        return {"queued": len(ids)}

    raise ApiError(404, "not_found")


