_geo_cache = {}
_geo_lock = threading.Lock()
_geo_last = [0.0]


def http_json(url, timeout=6):
    req = urllib.request.Request(url, headers={"User-Agent": "YukFura/1.0 (logistics app)", "Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read(300000).decode("utf-8"))


def geo_cached(key, fn, throttle=False):
    now = time.time()
    hit = _geo_cache.get(key)
    if hit and now - hit[0] < 3600:
        return hit[1]
    if throttle:                      # Nominatim siyosati: sekundiga 1 so'rov
        with _geo_lock:
            wait = 1.05 - (time.time() - _geo_last[0])
            if wait > 0:
                time.sleep(wait)
            _geo_last[0] = time.time()
    val = fn()
    if len(_geo_cache) > 2000:
        _geo_cache.clear()
    _geo_cache[key] = (now, val)
    return val


def geo_search(text):
    def go():
        url = ("https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&accept-language=uz,ru&q="
               + urllib.parse.quote(text))
        return [{"name": ", ".join(x.get("display_name", "").split(", ")[:3]), "lat": float(x["lat"]), "lon": float(x["lon"])}
                for x in http_json(url)]
    return geo_cached("s:" + text.lower(), go, True)


def geo_reverse(lat, lon):
    def go():
        url = ("https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=13&accept-language=uz,ru&lat=%.5f&lon=%.5f" % (lat, lon))
        d = http_json(url)
        a = d.get("address") or {}
        parts = [a.get("city") or a.get("town") or a.get("village") or a.get("county"), a.get("state")]
        name = ", ".join(p for p in parts if p) or ", ".join((d.get("display_name") or "").split(", ")[:2])
        return {"name": name}
    return geo_cached("r:%.3f,%.3f" % (lat, lon), go, True)


def road_route(lat1, lon1, lat2, lon2):
    """Yo'l bo'yicha masofa (km) va vaqt (daqiqa). Xizmat javob bermasa None."""
    def go():
        url = "https://router.project-osrm.org/route/v1/driving/%.5f,%.5f;%.5f,%.5f?overview=false" % (lon1, lat1, lon2, lat2)
        d = http_json(url)
        r = d["routes"][0]
        return {"km": round(r["distance"] / 1000.0, 1), "minutes": round(r["duration"] / 60.0)}
    try:
        return geo_cached("d:%.3f,%.3f,%.3f,%.3f" % (lat1, lon1, lat2, lon2), go)
    except Exception as e:
        print("OSRM xatosi:", e)
        return None


def document(c, viewer):
    """Yuk xati (hujjat) ma'lumotlari: ikkala tomon uchun bir xil."""
    owner = N("get_user")(c["owner_id"])
    drv = N("get_user")(c["driver_id"]) if row_get(c, "driver_id") else None
    price = row_get(c, "agreed_price") or c["price"]
    return {
        "number": "YF-" + str(c["id"]).zfill(6), "status": c["status"],
        "created_at": row_get(c, "created_at"), "taken_at": row_get(c, "taken_at"), "delivered_at": row_get(c, "delivered_at"),
        "cargo": {"type": c["cargo_type"], "weight": c["weight"]},
        "route": {"from": c["from_loc"], "to": c["to_loc"], "km": row_get(c, "road_km") or km_between(row_get(c, "lat"), row_get(c, "lon"), row_get(c, "to_lat"), row_get(c, "to_lon"))},
        "price": round(price or 0),
        "owner": {"name": owner["full_name"], "phone": owner["phone"]} if owner else None,
        "driver": ({"name": drv["full_name"], "phone": drv["phone"],
                    "car": ((row_get(drv, "car_brand", "") or "") + " " + (row_get(drv, "car_model", "") or "")).strip(),
                    "plate": row_get(drv, "car_plate", "")} if drv else None),
        "agreed_driver": row_get(c, "driver_agreed_at"), "agreed_owner": row_get(c, "owner_agreed_at"),
        "owner_fee": round(row_get(c, "owner_fee", 0) or 0), "driver_fee": round(row_get(c, "driver_fee", 0) or 0),
        "operator": OPERATOR,
    }


def register(uid, body):
    existing = N("get_user")(uid)
    if N("is_complete")(existing):
        raise ApiError(409, "exists")
    if not (existing and row_get(existing, "terms_at")):
        raise ApiError(400, "consent")
    if not rate_ok("reg:" + str(uid), 5, 3600):
        raise ApiError(429, "rate")
    role = body.get("role")
    name, phone = clean(body.get("full_name"), 80), clean(body.get("phone"), 25)
    if not re.match(r"^[+\d][\d\s\-()]{6,22}$", phone):
        raise ApiError(400, "invalid")
    lang = N("lang_of")(uid)
    esc = N("esc")
    if role == "owner":
        N("save_user")(uid, role="owner", full_name=name, phone=phone, lang=lang)
        N("notify_admin")("Yangi yuk beruvchi (ilova) ro'yxatdan o'tdi:\n" + esc(name) + "\n" + esc(phone) + "\nID: " + str(uid))
        return {"ok": True}
    if role != "driver":
        raise ApiError(400, "invalid")
    brand, model, plate = clean(body.get("car_brand"), 40), clean(body.get("car_model"), 40), clean(body.get("car_plate"), 20)
    if body.get("consent") is not True:
        raise ApiError(400, "consent")
    raw = photo_bytes(body.get("photo"))
    import io
    types = N("types")
    bot = N("bot")
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("Tasdiqlash", callback_data="verify_" + str(uid)),
           types.InlineKeyboardButton("Rad etish", callback_data="reject_" + str(uid)))
    f = io.BytesIO(raw)
    f.name = "doc.jpg"
    try:
        sent = bot.send_photo(N("ADMIN_ID"), f, caption=(
            "Yangi furachi (ilova) tasdiqlash kutmoqda:\n" + esc(name) + "\n" + esc(phone) + "\n"
            + esc(brand) + " " + esc(model) + "\nDavlat raqami: " + esc(plate) + "\nID: " + str(uid)), reply_markup=kb)
        file_id = sent.photo[-1].file_id
    except Exception as e:
        print("Ilovadan guvohnoma rasmini adminga yuborishda xato:", e)
        raise ApiError(502, "upload")
    import datetime
    N("save_user")(uid, role="driver", full_name=name, phone=phone, car_brand=brand, car_model=model,
                   car_plate=plate, verify_photo=file_id, verified=0, consent_at=str(datetime.datetime.now()), lang=lang)
    N("safe_send")(uid, N("T")(uid, "reg_done_driver"))
    return {"ok": True}


# ------------------------------------------------------------------ HTTP

def csp():
    return ("default-src 'self'; img-src 'self' data: blob: https://*.tile.openstreetmap.org https://cdnjs.cloudflare.com; "
            "style-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com; "
            "script-src 'self' https://cdnjs.cloudflare.com; connect-src 'self'; media-src 'self' " + media_hosts() + "; "
            "frame-ancestors 'none'; base-uri 'none'; form-action 'none'")


SEC = {
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
    "X-Frame-Options": "DENY",
    "Permissions-Policy": "geolocation=(self), camera=(self), microphone=()",
}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "YukFura"

    def log_message(self, *a):
        pass

    def ip(self):
        xf = self.headers.get("X-Forwarded-For", "")
        return (xf.split(",")[0].strip() if xf else self.client_address[0]) or "?"

    def session(self):
        a = self.headers.get("Authorization", "")
        return a[7:].strip() if a.startswith("Bearer ") and len(a) < 200 else None

    def send(self, status, payload, ctype, extra=None, head=False):
        self.send_response(status)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(payload)))
        for k, v in SEC.items():
            self.send_header(k, v)
        self.send_header("Content-Security-Policy", csp())
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        if not head:
            self.wfile.write(payload)

    def json(self, status, obj, head=False):
        self.send(status, json.dumps(obj, ensure_ascii=False).encode("utf-8"), "application/json; charset=utf-8",
                  {"Cache-Control": "no-store"}, head)

    def handle_any(self, method):
        head = method == "HEAD"
        if head:
            method = "GET"
        try:
            u = urlparse(self.path)
            path = u.path
            if not rate_ok("ip:" + self.ip(), 300):
                raise ApiError(429, "rate")
            if path.startswith("/api/"):
                body = {}
                if method == "POST":
                    try:
                        n = int(self.headers.get("Content-Length", "0"))
                    except ValueError:
                        n = -1
                    if n < 0 or n > MAX_BODY:
                        raise ApiError(413, "invalid")
                    raw = self.rfile.read(n) if n else b""
                    if raw:
                        try:
                            body = json.loads(raw.decode("utf-8"))
                        except Exception:
                            raise ApiError(400, "invalid")
                        if not isinstance(body, dict):
                            raise ApiError(400, "invalid")
                res = route(self, method, path, parse_qs(u.query), body)
                if isinstance(res, tuple) and res and res[0] == "raw":
                    self.send(200, res[1], res[2], {"Cache-Control": "no-store"}, head)
                else:
                    self.json(200, res, head)
                return
            if method != "GET":
                raise ApiError(405, "bad_action")
            if path == "/.well-known/assetlinks.json":
                sha = os.getenv("ANDROID_SHA256", "").strip()
                pkg = os.getenv("ANDROID_PACKAGE", "uz.yukfura.app")
                data = [{"relation": ["delegate_permission/common.handle_all_urls"],
                         "target": {"namespace": "android_app", "package_name": pkg,
                                    "sha256_cert_fingerprints": [x.strip() for x in sha.split(",") if x.strip()]}}] if sha else []
                self.send(200, json.dumps(data).encode("utf-8"), "application/json", {"Cache-Control": "no-cache"}, head)
                return
            if path == "/delete-account":
                lang = (parse_qs(u.query).get("l") or ["uz"])[0]
                self.send(200, delete_page("ru" if lang == "ru" else "uz", OPERATOR_CONTACT).encode("utf-8"),
                          "text/html; charset=utf-8", {"Cache-Control": "no-cache"}, head)
                return
            if path in ("/oferta", "/privacy"):
                lang = (parse_qs(u.query).get("l") or ["uz"])[0]
                page = legal_page(path[1:], "ru" if lang == "ru" else "uz", OPERATOR, OPERATOR_CONTACT,
                                  N("OWNER_FOIZ") * 100, N("DRIVER_FOIZ") * 100)
                self.send(200, page.encode("utf-8"), "text/html; charset=utf-8", {"Cache-Control": "no-cache"}, head)
                return
            if path in ("/", "/index.html", "/health"):
                path = "/index.html" if path != "/health" else "/health"
            if path == "/health":
                self.send(200, b"ok", "text/plain; charset=utf-8", None, head)
                return
            a = ASSETS.get(path)
            if not a:
                self.send(404, b"not found", "text/plain; charset=utf-8", None, head)
                return
            cache = "no-cache" if path in ("/index.html", "/sw.js", "/app.js", "/style.css") else "public, max-age=86400"
            self.send(200, a[0], a[1], {"Cache-Control": cache}, head)
        except ApiError as e:
            try:
                self.json(e.status, {"error": e.code}, head)
            except Exception:
                pass
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:
            print("API xatosi:", repr(e))
            try:
                self.json(500, {"error": "generic"}, head)
            except Exception:
                pass

    def do_GET(self):
        self.handle_any("GET")

    def do_HEAD(self):
        self.handle_any("HEAD")

    def do_POST(self):
        self.handle_any("POST")

    def do_PUT(self):
        self.handle_any("PUT")

    def do_DELETE(self):
        self.handle_any("DELETE")


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    request_queue_size = 64


def make_server(port, ns, host="0.0.0.0"):
    global NS
    NS = ns
    return _Server((host, port), Handler)


def start_server(port, ns):
    """bot.py chaqiradi: serverni fon oqimda ishga tushiradi."""
    srv = make_server(port, ns)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    print("Ilova serveri ishga tushdi, port:", port)
    return srv
